L000476	\subsection{Fourth order coefficient}
L000477	
L000478	We report here the computation of the $W^4$ contribution to the inverse localization length, in the regime in which the $W^2$ contribution vanishes, namely $2k < k_0 < \pi - k$.
L000479	To do so, we need to compute the diagrams $\Sigma^{(2)}_{\mathrm{cross}}(k,E)$ and $\Sigma^{(2)}_{\mathrm{non-cross}}(k,E)$, given by
L000480	\begin{equation}
L000481	    \Sigma^{(2)}_{\mathrm{cross}}(k,E) = W^4 \int_{-\pi}^{\pi} \frac{dq_1}{2\pi}\int_{-\pi}^{\pi} \frac{dq_2}{2\pi} S(q_1)S(q_2)
L000482	    G_0(k-q_1,E)G_0(k-q_2,E)G_0(k-q_1-q_2,E),
L000483	\end{equation}
L000484	\begin{equation}
L000485	    \Sigma^{(2)}_{\mathrm{non-cross}}(k,E) = W^4 \int_{-\pi}^{\pi} \frac{dq_1}{2\pi}\int_{-\pi}^{\pi} \frac{dq_2}{2\pi} S(q_1)S(q_2)
L000486	    [G_0(k-q_1,E)]^2G_0(k-q_1-q_2,E).
L000487	\end{equation}
L000488	When $\Sigma^{(1)}(k,\epsilon_k) = 0$, we get, following our discussion in the main text,
L000489	\begin{equation}
L000490	    \mathrm{Im}\, \Sigma^{(2)}_{\mathrm{cross}}(k,\epsilon_k) = -\pi W^4 \int_{-\pi}^{\pi} \frac{dq_1}{2\pi}\int_{-\pi}^{\pi} \frac{dq_2}{2\pi} S(q_1)S(q_2)
L000491	    \mathcal{P}\left(\frac{1}{\epsilon_k - \epsilon_{k-q_1}}\right)\mathcal{P}\left(\frac{1}{\epsilon_k - \epsilon_{k-q_2}}\right)\delta(\epsilon_k-\epsilon_{k-q_1-q_2}),
L000492	\end{equation}
L000493	\begin{equation}
L000494	    \mathrm{Im}\, \Sigma^{(2)}_{\mathrm{non-cross}}(k,\epsilon_k) = -\pi W^4 \int_{-\pi}^{\pi} \frac{dq_1}{2\pi}\int_{-\pi}^{\pi} \frac{dq_2}{2\pi} S(q_1)S(q_2)
L000495	    \left[\mathcal{P}\left(\frac{1}{\epsilon_k - \epsilon_{k-q_1}}\right)\right]^2\delta(\epsilon_k-\epsilon_{k-q_1-q_2}).
L000496	\end{equation}
L000497	The $\delta$-function, in the case of back-scattering we are interested in, is given by
L000498	\begin{equation}
L000499	    \delta(\epsilon_k-\epsilon_{k-q_1-q_2}) = \frac{\delta(q_2-2k+q_1)}{2 \sin(k)},
L000500	\end{equation}
L000501	and thus
L000502	\begin{equation}
L000503	    \mathrm{Im}\, \Sigma^{(2)}_{\mathrm{cross}}(k,\epsilon_k) = -\frac{\pi W^4}{32\pi^2 \sin(k)} \int_{[-\pi,-k_0]\cup [k_0,\pi]} dq_1
L000504	    \left(\frac{1}{\cos(k) - \cos(k-q_1)}\right)\left(\frac{1}{\cos(k) - \cos(-k+q_1)}\right),
L000505	\end{equation}
L000506	\begin{equation}
L000507	    \mathrm{Im}\, \Sigma^{(2)}_{\mathrm{non-cross}}(k,\epsilon_k) = -\frac{\pi W^4}{32\pi^2 \sin(k)} \int_{[-\pi,-k_0]\cup [k_0,\pi]} dq_1
L000508	    \left(\frac{1}{\cos(k) - \cos(k-q_1)}\right)^2.
L000509	\end{equation}
L000510	The two integrals are equal, and thus
L000511	\begin{align}
L000512	    \mathrm{Im}\, \Sigma^{(2)}(k,\epsilon_k) &= -\frac{\pi W^4}{16\pi^2 \sin(k)} \int_{[-\pi,-k_0]\cup [k_0,\pi]} dq_1
L000513	    \left(\frac{1}{\cos(k) - \cos(k-q_1)}\right)^2\\
L000514	    &= -\frac{\pi W^4}{16\pi^2 \sin(k)} \left[
L000515	    \frac{1}{2} \csc ^2(k) \left(-\csc (k) \sin \left(\frac{k_0}{2}\right) \left(\csc
L000516	   \left(k-\frac{k_0}{2}\right)+\csc \left(k+\frac{k_0}{2}\right)\right)\right.\right.\\
L000517	   & \qquad \qquad \left.\left.
L000518	   -2
L000519	   \cot (k) \log \left(\sin \left(k+\frac{k_0}{2}\right) \left(-\csc
L000520	   \left(k-\frac{k_0}{2}\right)\right)\right)+2 \cot
L000521	   \left(\frac{k_0}{2}\right)\right) \right].
L000522	\end{align}
L000523	The inverse localization length is then
L000524	\begin{align}
L000525	 \label{eq:second-order}
L000526	    \frac{1}{\xi(k)} = \frac{W^4}{32\pi \sin^2(k)} &\left[
L000527	    \frac{1}{2} \csc ^2(k) \left(-\csc (k) \sin \left(\frac{k_0}{2}\right) \left(\csc
L000528	   \left(k-\frac{k_0}{2}\right)+\csc \left(k+\frac{k_0}{2}\right)\right)\right.\right.\\
L000529	   &\left.\left.
L000530	   -2
L000531	   \cot (k) \log \left(\sin \left(k+\frac{k_0}{2}\right) \left(-\csc
L000532	   \left(k-\frac{k_0}{2}\right)\right)\right)+2 \cot
L000533	   \left(\frac{k_0}{2}\right)\right) \right].
L000534	\end{align}
L000535	One can compute the leading order term in $\pi - k_0$, or equivalently $1/2 - \chi$. By expanding the above expression around $k_0 = \pi$, we get.
L000536	\begin{align}
L000537	    \frac{1}{\xi(k)} = \frac{W^4}{32\pi \sin^2(k)}\frac{(\pi-k_0)}{2} \left[\sec ^2(k) - \frac{1}{24} (\pi - k_0 )^2 (\cos (2 k)-5)
L000538	   \sec ^4(k)+O\left((\pi -k_0)^3\right)\right]
L000539	\end{align}
